// BLUE-17
/**
 * Sums the `amount` field of each element in the rows array.
 * @param {Array<{amount:number}>} rows
 * @returns {number} total sum of amounts
 */
export function total(rows) {
  return rows.reduce((sum, row) => sum + row.amount, 0);
}

